<?php
namespace App\Http\Controllers;
use App\Models\{User,Doctor,Appointment,ContactMessage};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,Hash,DB};
use Illuminate\Validation\Rule;
class HealthController extends Controller {
 private function admin():void{abort_unless(Auth::user()?->role==='admin',403);}
 public function welcome(){return view('welcome');}
 public function login(Request $r){if($r->isMethod('get'))return view('auth',['mode'=>'login']);$v=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($v))return back()->withErrors(['email'=>'Invalid login details'])->onlyInput('email');$r->session()->regenerate();return redirect()->route(Auth::user()->role==='admin'?'admin.dashboard':'home');}
 public function register(Request $r){if($r->isMethod('get'))return view('auth',['mode'=>'register']);$v=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|unique:users,email','phone'=>'nullable|string|max:30','password'=>'required|min:8|confirmed']);$v['role']='user';$u=User::create($v);Auth::login($u);$r->session()->regenerate();return redirect()->route('home');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('welcome');}
 public function home(){return view('home',['appointments'=>Auth::user()->appointments()->with('doctor')->latest()->get()]);}
 public function profile(Request $r){if($r->isMethod('post')){$v=$r->validate(['name'=>'required|max:150','email'=>['required','email',Rule::unique('users')->ignore(Auth::id())],'phone'=>'nullable|max:30','branch'=>'nullable|max:100','password'=>'nullable|min:8|confirmed']);if(empty($v['password']))unset($v['password']);Auth::user()->update($v);return back()->with('success','Profile updated');}return view('profile');}
 public function appointments(){return Auth::user()->role==='admin'?redirect()->route('admin.dashboard'):view('home',['appointments'=>Auth::user()->appointments()->with('doctor')->latest()->get()]);}
 public function book(Request $r){if($r->isMethod('get'))return view('book',['doctors'=>Doctor::where('active',true)->orderBy('name')->get()]);$v=$r->validate(['doctor_id'=>['required',Rule::exists('doctors','id')->where('active',true)],'patient_name'=>'required|max:150','patient_email'=>'required|email','patient_phone'=>'required|max:30','appointment_at'=>'required|date|after:now','notes'=>'nullable|max:2000']);$v['user_id']=Auth::id();$v['status']='Pending';Appointment::create($v);return redirect()->route('home')->with('success','Appointment saved successfully');}
 public function contact(Request $r){if($r->isMethod('get'))return view('contact');$v=$r->validate(['name'=>'required|max:150','email'=>'required|email','subject'=>'required|max:200','message'=>'required|max:5000']);$v['user_id']=Auth::id();ContactMessage::create($v);return back()->with('success','Message saved successfully');}
 public function dashboard(){ $this->admin();return view('admin.dashboard',['appointments'=>Appointment::with(['doctor','user'])->latest()->get(),'total'=>Appointment::count(),'monthly'=>Appointment::whereYear('appointment_at',now()->year)->whereMonth('appointment_at',now()->month)->count(),'patients'=>User::where('role','user')->count(),'doctors'=>Doctor::count(),'pending'=>Appointment::where('status','Pending')->count()]);}
 public function editAppointment(Request $r,Appointment $appointment){$this->admin();if($r->isMethod('get'))return view('admin.edit-appointment',compact('appointment')+['doctors'=>Doctor::all()]);$v=$r->validate(['doctor_id'=>'required|exists:doctors,id','patient_name'=>'required|max:150','patient_email'=>'required|email','patient_phone'=>'required|max:30','appointment_at'=>'required|date','status'=>['required',Rule::in(['Pending','Confirmed','Cancelled','Completed'])],'notes'=>'nullable|max:2000']);$appointment->update($v);return redirect()->route('admin.dashboard')->with('success','Appointment updated');}
 public function deleteAppointment(Appointment $appointment){$this->admin();$appointment->delete();return back()->with('success','Appointment deleted');}
 public function doctors(){ $this->admin();return view('admin.doctors',['doctors'=>Doctor::orderBy('name')->get()]);}
 public function addDoctor(Request $r){$this->admin();$v=$r->validate(['name'=>'required|max:150','specialty'=>'required|max:150','phone'=>'nullable|max:30','email'=>'nullable|email']);Doctor::create($v);return back()->with('success','Doctor added');}
 public function editDoctor(Request $r,Doctor $doctor){$this->admin();if($r->isMethod('get'))return view('admin.edit-doctor',compact('doctor'));$v=$r->validate(['name'=>'required|max:150','specialty'=>'required|max:150','phone'=>'nullable|max:30','email'=>'nullable|email','active'=>'required|boolean']);$doctor->update($v);return redirect()->route('admin.doctors')->with('success','Doctor updated');}
 public function deleteDoctor(Doctor $doctor){$this->admin();if($doctor->appointments()->exists())return back()->withErrors(['doctor'=>'Cannot delete a doctor with appointments. Deactivate instead.']);$doctor->delete();return back()->with('success','Doctor deleted');}
 public function patients(){ $this->admin();return view('admin.patients',['patients'=>User::where('role','user')->withCount('appointments')->get()]);}
 public function editPatient(Request $r,User $patient){$this->admin();abort_unless($patient->role==='user',404);if($r->isMethod('get'))return view('admin.edit-patient',compact('patient'));$v=$r->validate(['name'=>'required|max:150','email'=>['required','email',Rule::unique('users')->ignore($patient->id)],'phone'=>'nullable|max:30']);$patient->update($v);return redirect()->route('admin.patients')->with('success','Patient updated');}
 public function messages(){ $this->admin();return view('admin.messages',['messages'=>ContactMessage::latest()->get()]);}
}
